diff --git a/crates/op-plugins/src/bin/gen_tched_router_config_surface.rs b/crates/op-plugins/src/bin/gen_tched_router_config_surface.rs
new file mode 100644
index 00000000..b2b73617
--- /dev/null
+++ b/crates/op-plugins/src/bin/gen_tched_router_config_surface.rs
@@ -0,0 +1,316 @@
+//! Generator: emit `tched_router_config_surface.rs` from the REAL upstream
+//! config schema (`schemars::schema_for!(zeroclaw::Config)`).
+//!
+//! The upstream crate is the single source of truth: every config section
+//! becomes a `Get<Section>Config` method typed by the upstream section type,
+//! plus `GetConfig` (full, secret-masked) and `PatchConfig` (validated
+//! mutation). Local 3tched Router configuration structs are emitted as plain
+//! config sections too ("configurable options are just configurations").
+//!
+//! Regenerate after bumping the zeroclaw dependency:
+//!
+//! ```text
+//! cargo run -p op-plugins --bin gen_tched_router_config_surface
+//! ```
+
+use serde_json::Value;
+use std::fmt::Write as _;
+use std::path::PathBuf;
+
+/// One config section discovered from the upstream schema.
+struct Section {
+    /// serde key on `zeroclaw::Config` (e.g. "gateway", "channels_config").
+    key: String,
+    /// Rust type of the section value (e.g. "zeroclaw::config::GatewayConfig").
+    ty: String,
+}
+
+/// Local (3tched Router-owned) configuration sections — plain configurations,
+/// not a separate "options" projection. Types live in `super::tched_router`.
+const LOCAL_SECTIONS: &[(&str, &str)] = &[
+    ("model_assignments", "super::tched_router::ModelAssignments"),
+    (
+        "memory_namespaces",
+        "Vec<super::tched_router::MemoryNamespaceOption>",
+    ),
+    (
+        "registration_service",
+        "super::tched_router::RegistrationServiceSchema",
+    ),
+    ("user_container", "super::tched_router::UserContainerOptions"),
+    ("identity_chain", "super::tched_router::IdentityOptions"),
+    ("privacy_policy", "super::tched_router::PrivacyOptions"),
+];
+
+/// `$defs` names whose Rust path is NOT `zeroclaw::config::<Name>`.
+fn type_path_exception(def: &str) -> Option<&'static str> {
+    Some(match def {
+        "BrowserDelegateConfig" => "zeroclaw::tools::browser_delegate::BrowserDelegateConfig",
+        "ModelProviderConfig" => "zeroclaw::config::schema::ModelProviderConfig",
+        _ => return None,
+    })
+}
+
+fn type_path(def: &str) -> String {
+    type_path_exception(def)
+        .map(str::to_string)
+        .unwrap_or_else(|| format!("zeroclaw::config::{def}"))
+}
+
+fn pascal(s: &str) -> String {
+    s.split('_')
+        .filter(|p| !p.is_empty())
+        .map(|p| {
+            let mut c = p.chars();
+            match c.next() {
+                Some(f) => f.to_ascii_uppercase().to_string() + c.as_str(),
+                None => String::new(),
+            }
+        })
+        .collect()
+}
+
+fn kebab(s: &str) -> String {
+    s.replace('_', "-")
+}
+
+/// `Get` + Pascal(section) + `Config`, without doubling a trailing `Config`.
+fn method_name(section_key: &str) -> String {
+    let p = pascal(section_key);
+    if p.ends_with("Config") {
+        format!("Get{p}")
+    } else {
+        format!("Get{p}Config")
+    }
+}
+
+/// Extract sections from the upstream Config JSON Schema.
+fn discover_sections(schema: &Value) -> Vec<Section> {
+    let props = schema
+        .get("properties")
+        .and_then(Value::as_object)
+        .expect("Config schema has properties");
+    let mut out = Vec::new();
+    for (key, prop) in props {
+        let ref_of = |v: &Value| {
+            v.get("$ref")
+                .and_then(Value::as_str)
+                .map(|r| r.rsplit('/').next().unwrap_or(r).to_string())
+        };
+        let ty = if let Some(def) = ref_of(prop) {
+            type_path(&def)
+        } else if prop.get("type").and_then(Value::as_str) == Some("array") {
+            match prop.get("items").and_then(ref_of) {
+                Some(def) => format!("Vec<{}>", type_path(&def)),
+                None => continue, // untyped array — skip
+            }
+        } else if prop.get("type").and_then(Value::as_str) == Some("object") {
+            match prop.get("additionalProperties").and_then(ref_of) {
+                Some(def) => format!("std::collections::HashMap<String, {}>", type_path(&def)),
+                None => "std::collections::HashMap<String, String>".to_string(),
+            }
+        } else {
+            continue; // scalar top-level key — covered by GetConfig
+        };
+        out.push(Section {
+            key: key.clone(),
+            ty,
+        });
+    }
+    out.sort_by(|a, b| a.key.cmp(&b.key));
+    out
+}
+
+fn main() {
+    let out_path = std::env::args().nth(1).map(PathBuf::from).unwrap_or_else(|| {
+        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
+            .join("src/state_plugins/tched_router_config_surface.rs")
+    });
+
+    let schema = serde_json::to_value(schemars::schema_for!(zeroclaw::Config))
+        .expect("Config schema serializes");
+    let upstream = discover_sections(&schema);
+
+    let mut s = String::new();
+    s.push_str(
+        "//! GENERATED by `cargo run -p op-plugins --bin gen_tched_router_config_surface`.\n\
+         //! DO NOT EDIT — regenerate after bumping the `zeroclaw` dependency.\n\
+         //!\n\
+         //! Complete 3tched Router config surface: every upstream config section\n\
+         //! as a real-typed `Get<Section>Config` method, plus `GetConfig` (full,\n\
+         //! secret-masked) and `PatchConfig` (validated mutation). Local 3tched\n\
+         //! Router configuration structs are plain config sections here — there\n\
+         //! is no separate \"configurable options\" projection. No cache, no\n\
+         //! projection: reads parse the current config; mutations land in state.\n\n",
+    );
+    s.push_str("use super::common::errors::TchedRouterError;\n");
+    s.push_str("use super::plugin_scaffold_helpers::method_decl_from_schemars_with_output;\n");
+    s.push_str("use super::tched_router::{DispatchOutcome, TchedRouterState};\n");
+    s.push_str("use op_state_store::{CapabilityDecl, PluginSchema, SideEffect};\n");
+    s.push_str("use serde::{Deserialize, Serialize};\n");
+    s.push_str("use serde_json::Value as JsonValue;\n\n");
+
+    // ── Shared input/output structs ─────────────────────────────────────────
+    s.push_str(
+        "/// Empty input for config read methods.\n\
+         #[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]\n\
+         pub struct ConfigMethodInput {}\n\n",
+    );
+    s.push_str(
+        "/// Output for `GetConfig` — the full upstream configuration, typed by\n\
+         /// the real `zeroclaw::Config`. Secrets are masked by dispatch.\n\
+         #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]\n\
+         #[schemars(extend(\"x-oscal-subid\" = \"exp.service.3tched-router.config.result@v1\"))]\n\
+         pub struct GetConfigOutput {\n\
+         \x20   /// Full upstream configuration.\n\
+         \x20   pub config: zeroclaw::Config,\n\
+         }\n\n",
+    );
+    s.push_str(
+        "/// Input for `PatchConfig`: replace one config section.\n\
+         #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]\n\
+         pub struct PatchConfigInput {\n\
+         \x20   /// Section key (e.g. `gateway`, `memory`, `channels_config`).\n\
+         \x20   pub section: String,\n\
+         \x20   /// New section value; validated against the real upstream type.\n\
+         \x20   pub value: JsonValue,\n\
+         }\n\n\
+         /// Output for `PatchConfig` — the validated value that was applied.\n\
+         #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]\n\
+         pub struct PatchConfigOutput {\n\
+         \x20   /// Section that was patched.\n\
+         \x20   pub section: String,\n\
+         \x20   /// Validated value now in effect.\n\
+         \x20   pub value: JsonValue,\n\
+         }\n\n",
+    );
+
+    // ── Per-section output structs ──────────────────────────────────────────
+    let mut all: Vec<(&str, String, bool)> = Vec::new(); // (key, ty, local)
+    for sec in &upstream {
+        all.push((&sec.key, sec.ty.clone(), false));
+    }
+    for (key, ty) in LOCAL_SECTIONS {
+        all.push((key, (*ty).to_string(), true));
+    }
+    for (key, ty, _local) in &all {
+        let m = method_name(key);
+        let _ = writeln!(
+            s,
+            "/// Output for `{m}`.\n\
+             #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]\n\
+             #[schemars(extend(\"x-oscal-subid\" = \"exp.service.3tched-router.{}-config.result@v1\"))]\n\
+             pub struct {m}Output {{\n\
+             \x20   /// Current `{key}` configuration.\n\
+             \x20   pub config: {ty},\n\
+             }}\n",
+            kebab(key)
+        );
+    }
+
+    // ── Method table + registration ─────────────────────────────────────────
+    s.push_str("\n/// (method, section key, source) for every config read.\n");
+    s.push_str("pub const SECTIONS: &[(&str, &str, SectionSource)] = &[\n");
+    for (key, _ty, local) in &all {
+        let src = if *local { "Local" } else { "Upstream" };
+        let _ = writeln!(
+            s,
+            "    (\"{}\", \"{key}\", SectionSource::{src}),",
+            method_name(key)
+        );
+    }
+    s.push_str("];\n\n");
+    s.push_str("/// Where a config section is read from.\n");
+    s.push_str("#[derive(Debug, Clone, Copy, PartialEq, Eq)]\n");
+    s.push_str("pub enum SectionSource {\n    /// Upstream `zeroclaw::Config` (the config file).\n    Upstream,\n    /// Local 3tched Router state (a plain configuration).\n    Local,\n}\n\n");
+
+    s.push_str("/// Every method owned by this surface (for dispatch membership checks).\n");
+    s.push_str("pub const CONFIG_METHODS: &[&str] = &[\n    \"GetConfig\",\n    \"PatchConfig\",\n");
+    for (key, _ty, _local) in &all {
+        let _ = writeln!(s, "    \"{}\",", method_name(key));
+    }
+    s.push_str("];\n\n");
+
+    // register()
+    s.push_str(
+        "/// Register every config method and its declared capability on the schema.\n\
+         ///\n\
+         /// The plugin is the single declaration point: each method's\n\
+         /// `required_capability` has a matching `schema.capabilities` entry\n\
+         /// (closure-clean under `validate_capability_closure`).\n\
+         pub fn register_config_methods(schema: &mut PluginSchema) {\n",
+    );
+    s.push_str(
+        "    schema.methods.insert(\n\
+         \x20       \"GetConfig\".to_string(),\n\
+         \x20       method_decl_from_schemars_with_output::<ConfigMethodInput, GetConfigOutput>(\n\
+         \x20           \"GetConfig\",\n\
+         \x20           SideEffect::Read,\n\
+         \x20           true,\n\
+         \x20           \"cap.software.3tched-router.config.read@v1\",\n\
+         \x20           \"obs.service.3tched-router.config.get@v1\",\n\
+         \x20       ),\n\
+         \x20   );\n\
+         \x20   schema.capabilities.insert(\n\
+         \x20       \"cap.software.3tched-router.config.read@v1\".to_string(),\n\
+         \x20       CapabilityDecl {\n\
+         \x20           id: \"cap.software.3tched-router.config.read@v1\".to_string(),\n\
+         \x20           description: \"Read the full 3tched Router configuration (secrets masked).\".to_string(),\n\
+         \x20       },\n\
+         \x20   );\n\
+         \x20   schema.methods.insert(\n\
+         \x20       \"PatchConfig\".to_string(),\n\
+         \x20       method_decl_from_schemars_with_output::<PatchConfigInput, PatchConfigOutput>(\n\
+         \x20           \"PatchConfig\",\n\
+         \x20           SideEffect::Mutation,\n\
+         \x20           false,\n\
+         \x20           \"cap.software.3tched-router.config.write@v1\",\n\
+         \x20           \"mut.service.3tched-router.config.patch@v1\",\n\
+         \x20       ),\n\
+         \x20   );\n\
+         \x20   schema.capabilities.insert(\n\
+         \x20       \"cap.software.3tched-router.config.write@v1\".to_string(),\n\
+         \x20       CapabilityDecl {\n\
+         \x20           id: \"cap.software.3tched-router.config.write@v1\".to_string(),\n\
+         \x20           description: \"Patch 3tched Router configuration sections (validated).\".to_string(),\n\
+         \x20       },\n\
+         \x20   );\n",
+    );
+    for (key, _ty, _local) in &all {
+        let m = method_name(key);
+        let k = kebab(key);
+        let _ = writeln!(
+            s,
+            "    schema.methods.insert(\n\
+             \x20       \"{m}\".to_string(),\n\
+             \x20       method_decl_from_schemars_with_output::<ConfigMethodInput, {m}Output>(\n\
+             \x20           \"{m}\",\n\
+             \x20           SideEffect::Read,\n\
+             \x20           true,\n\
+             \x20           \"cap.software.3tched-router.{k}-config.read@v1\",\n\
+             \x20           \"obs.service.3tched-router.{k}-config.get@v1\",\n\
+             \x20       ),\n\
+             \x20   );\n\
+             \x20   schema.capabilities.insert(\n\
+             \x20       \"cap.software.3tched-router.{k}-config.read@v1\".to_string(),\n\
+             \x20       CapabilityDecl {{\n\
+             \x20           id: \"cap.software.3tched-router.{k}-config.read@v1\".to_string(),\n\
+             \x20           description: \"Read the 3tched Router `{key}` configuration.\".to_string(),\n\
+             \x20       }},\n\
+             \x20   );"
+        );
+    }
+    s.push_str("}\n\n");
+
+    // ── Dispatch ────────────────────────────────────────────────────────────
+    s.push_str(include_str!("tched_router_config_surface.dispatch.inc"));
+
+    std::fs::write(&out_path, s).unwrap_or_else(|e| panic!("write {}: {e}", out_path.display()));
+    eprintln!(
+        "wrote {} ({} upstream sections, {} local, {} config methods)",
+        out_path.display(),
+        upstream.len(),
+        LOCAL_SECTIONS.len(),
+        all.len() + 2,
+    );
+}
diff --git a/crates/op-plugins/src/bin/tched_router_config_surface.dispatch.inc b/crates/op-plugins/src/bin/tched_router_config_surface.dispatch.inc
new file mode 100644
index 00000000..92fa2092
--- /dev/null
+++ b/crates/op-plugins/src/bin/tched_router_config_surface.dispatch.inc
@@ -0,0 +1,186 @@
+// ── Dispatch ────────────────────────────────────────────────────────────────
+
+/// Dispatch a config-surface method. Returns `None` when `method` is not
+/// owned by this surface so the caller can fall through to other dispatchers.
+pub fn dispatch_config_method(
+    method: &str,
+    json_args: &str,
+    state: &TchedRouterState,
+) -> Option<std::result::Result<DispatchOutcome, TchedRouterError>> {
+    match method {
+        "GetConfig" => Some(get_full_config()),
+        "PatchConfig" => Some(patch_config(json_args)),
+        other => SECTIONS
+            .iter()
+            .find(|(name, _, _)| *name == other)
+            .map(|(_, key, source)| read_section(key, *source, state)),
+    }
+}
+
+/// Path of the live 3tched Router config file.
+///
+/// Minimal mirror of upstream resolution for now: explicit
+/// `TCHED_ROUTER_CONFIG_PATH` / `ZEROCLAW_CONFIG_PATH` override, else the
+/// default `~/.zeroclaw/config.toml`. Upstream's full resolution (workspace
+/// marker, env dirs) should replace this once exposed by the `zeroclaw` crate.
+fn config_path() -> std::path::PathBuf {
+    if let Ok(p) = std::env::var("TCHED_ROUTER_CONFIG_PATH") {
+        return p.into();
+    }
+    if let Ok(p) = std::env::var("ZEROCLAW_CONFIG_PATH") {
+        return p.into();
+    }
+    dirs::home_dir()
+        .unwrap_or_else(|| std::path::PathBuf::from("/root"))
+        .join(".zeroclaw")
+        .join("config.toml")
+}
+
+/// Read the config file and parse it through the REAL upstream type — an
+/// invalid file is an error here, never a silent partial read.
+fn load_upstream_value() -> std::result::Result<JsonValue, TchedRouterError> {
+    let path = config_path();
+    let text = std::fs::read_to_string(&path).map_err(|e| TchedRouterError::ExecutionDenied {
+        reason: format!("read {}: {e}", path.display()),
+    })?;
+    let config: zeroclaw::Config =
+        toml::from_str(&text).map_err(|e| TchedRouterError::ExecutionDenied {
+            reason: format!("parse {}: {e}", path.display()),
+        })?;
+    serde_json::to_value(&config).map_err(|e| TchedRouterError::ExecutionDenied {
+        reason: format!("serialize config: {e}"),
+    })
+}
+
+fn read_section(
+    key: &str,
+    source: SectionSource,
+    state: &TchedRouterState,
+) -> std::result::Result<DispatchOutcome, TchedRouterError> {
+    let root = match source {
+        SectionSource::Upstream => load_upstream_value()?,
+        SectionSource::Local => {
+            serde_json::to_value(state).map_err(|e| TchedRouterError::ExecutionDenied {
+                reason: format!("serialize state: {e}"),
+            })?
+        }
+    };
+    let value = root
+        .get(key)
+        .cloned()
+        .ok_or_else(|| TchedRouterError::ExecutionDenied {
+            reason: format!("config section missing: {key}"),
+        })?;
+    Ok(DispatchOutcome::plain(
+        serde_json::json!({ "config": value }),
+    ))
+}
+
+fn get_full_config() -> std::result::Result<DispatchOutcome, TchedRouterError> {
+    let mut root = load_upstream_value()?;
+    mask_secrets(&mut root);
+    Ok(DispatchOutcome::plain(
+        serde_json::json!({ "config": root }),
+    ))
+}
+
+fn patch_config(json_args: &str) -> std::result::Result<DispatchOutcome, TchedRouterError> {
+    #[derive(Deserialize)]
+    struct Args {
+        section: String,
+        value: JsonValue,
+    }
+    let args: Args =
+        serde_json::from_str(json_args).map_err(|e| TchedRouterError::ExecutionDenied {
+            reason: format!("PatchConfig args: {e}"),
+        })?;
+    if !SECTIONS
+        .iter()
+        .any(|(_, key, source)| *key == args.section && *source == SectionSource::Upstream)
+    {
+        return Err(TchedRouterError::ExecutionDenied {
+            reason: format!(
+                "PatchConfig: unknown or non-upstream section `{}` \
+                 (local sections are mutated via their own Set* methods)",
+                args.section
+            ),
+        });
+    }
+    if contains_masked_placeholder(&args.value) {
+        return Err(TchedRouterError::ExecutionDenied {
+            reason: "PatchConfig: value contains \"***MASKED***\" — masked \
+                     placeholders cannot be written"
+                .to_string(),
+        });
+    }
+    let path = config_path();
+    let text = std::fs::read_to_string(&path).map_err(|e| TchedRouterError::ExecutionDenied {
+        reason: format!("read {}: {e}", path.display()),
+    })?;
+    let mut doc: toml::Value =
+        toml::from_str(&text).map_err(|e| TchedRouterError::ExecutionDenied {
+            reason: format!("parse {}: {e}", path.display()),
+        })?;
+    let table = doc
+        .as_table_mut()
+        .ok_or_else(|| TchedRouterError::ExecutionDenied {
+            reason: "config root is not a table".to_string(),
+        })?;
+    let new_toml: toml::Value =
+        serde_json::from_value(args.value.clone()).map_err(|e| {
+            TchedRouterError::ExecutionDenied {
+                reason: format!("section value is not TOML-representable: {e}"),
+            }
+        })?;
+    table.insert(args.section.clone(), new_toml);
+    let serialized = toml::to_string(&doc).map_err(|e| TchedRouterError::ExecutionDenied {
+        reason: format!("serialize config: {e}"),
+    })?;
+    // Validate against the REAL upstream type before writing.
+    let _: zeroclaw::Config =
+        toml::from_str(&serialized).map_err(|e| TchedRouterError::ExecutionDenied {
+            reason: format!("patched config fails upstream validation: {e}"),
+        })?;
+    std::fs::write(&path, serialized).map_err(|e| TchedRouterError::ExecutionDenied {
+        reason: format!("write {}: {e}", path.display()),
+    })?;
+    Ok(DispatchOutcome::plain(serde_json::json!({
+        "section": args.section,
+        "value": args.value,
+    })))
+}
+
+/// Recursively mask secret-bearing keys in a config value.
+fn mask_secrets(value: &mut JsonValue) {
+    const SECRET_KEYS: &[&str] = &[
+        "api_key",
+        "apikey",
+        "token",
+        "secret",
+        "password",
+        "private_key",
+    ];
+    match value {
+        JsonValue::Object(map) => {
+            for (k, v) in map.iter_mut() {
+                let lk = k.to_ascii_lowercase();
+                if SECRET_KEYS.iter().any(|s| lk.contains(s)) && v.is_string() {
+                    *v = JsonValue::String("***MASKED***".to_string());
+                } else {
+                    mask_secrets(v);
+                }
+            }
+        }
+        JsonValue::Array(items) => items.iter_mut().for_each(mask_secrets),
+        _ => {}
+    }
+}
+
+fn contains_masked_placeholder(value: &JsonValue) -> bool {
+    match value {
+        JsonValue::String(s) => s == "***MASKED***",
+        JsonValue::Array(items) => items.iter().any(contains_masked_placeholder),
+        JsonValue::Object(map) => map.values().any(contains_masked_placeholder),
+        _ => false,
+    }
+}
